package com.compassCameraControl;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import java.awt.event.KeyEvent;

@ConfigGroup("compasscameracontrol")
public interface CompassCameraControlConfig extends Config
{
	@ConfigItem(
		keyName = "controlMode",
		name = "Mode",
		position = 1,
		description = "Cycle: North -> South -> East -> West (default)<br/>" +
			"Snap to Closest: Snaps the camera to the nearest cardinal direction<br/>" +
			"Snap to Facing: Snaps the camera to the player's facing direction<br/>" +
			"Snap then Cycle: Snaps to cardinal; re-click within 2 seconds to cycle"
	)
	default ControlMode controlMode()
	{
		return ControlMode.CYCLE;
	}

	@ConfigItem(
		keyName = "cycleOrder",
		name = "Cycle Order",
		position = 2,
		description = "Example 1: N-S-E-W<br/>" +
			"Example 2: S-N-E<br/>" +
			"Example 3: N-S"
	)
	default String cycleOrder()
	{
		return "N,S,E,W";
	}

	@ConfigItem(
		keyName = "shiftClickMode",
		name = "Shift-Click",
		position = 3,
		description = "Off: Always active, ignores Shift<br/>" +
			"On Shift: Only works when Shift is held<br/>" +
			"Off Shift: Only works when Shift is not held"
	)
	default ShiftMode shiftClickMode()
	{
		return ShiftMode.OFF;
	}

	@ConfigSection(
		name = "Keybindings",
		position = 4,
		closedByDefault = true,
		description = "Settings for snapping the camera to cardinal directions<br/>" +
			"To prevent these keys from appearing in chat<br/>" +
			"Enable the \"Key Remapping\" plugin (included with RuneLite)"
	)
	String cardinalKeybindingSnap = "cardinalKeybindingSnap";

	@ConfigItem(
		keyName = "snapFacingKey",
		name = "Snap Facing",
		description = "Snaps the camera to the player's facing direction on key press",
		position = 5,
		section = cardinalKeybindingSnap
	)
	default Keybind snapFacingKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "snapCloseKey",
		name = "Snap to Closest",
		description = "Snaps the camera to the nearest cardinal direction on key press",
		position = 6,
		section = cardinalKeybindingSnap
	)
	default Keybind snapCloseKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "cycleCardinalKey",
		name = "Cycle Cardinal",
		description = "Cycles through cardinal directions on key press",
		position = 7,
		section = cardinalKeybindingSnap
	)
	default Keybind cycleCardinalKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "snapThenCycleKey",
		name = "Snap then Cycle",
		position = 8,
		section = cardinalKeybindingSnap,
		description = "Snap to the closest allowed direction (within cycle order)<br/>" +
			"Quick re-press within 2 seconds cycles if already on an allowed direction"
	)
	default Keybind snapThenCycleKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "lookNorthKey",
		name = "Look North Key",
		description = "Face camera North on key press",
		position = 9,
		section = cardinalKeybindingSnap
	)
	default Keybind lookNorthKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "lookSouthKey",
		name = "Look South Key",
		description = "Face camera South on key press",
		position = 10,
		section = cardinalKeybindingSnap
	)
	default Keybind lookSouthKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "lookEastKey",
		name = "Look East Key",
		description = "Face camera East on key press",
		position = 11,
		section = cardinalKeybindingSnap
	)
	default Keybind lookEastKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "lookWestKey",
		name = "Look West Key",
		description = "Face camera West on key press",
		position = 12,
		section = cardinalKeybindingSnap
	)
	default Keybind lookWestKey() {
		return new Keybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "rotateFlipKey",
		name = "Rotate 180° Key",
		description = "Rotates the camera to opposite side (always 180°)",
		position = 13,
		section = cardinalKeybindingSnap
	)
	default Keybind rotateFlipKey() { return new Keybind(KeyEvent.VK_UNDEFINED, 0);}


	@ConfigItem(
		keyName = "rotateClockwiseKey",
		name = "Rotate Clockwise Key",
		position = 14,
		section = cardinalKeybindingSnap,
		description = "Rotate camera a user defined number of degrees clockwise<br/>" +
				"Based on Rotation Degree"
	)
	default Keybind rotateClockwiseKey() { return new Keybind(KeyEvent.VK_UNDEFINED, 0);}

	@ConfigItem(
		keyName = "rotateCounterclockwiseKey",
		name = "Rotate Counterclockwise Key",
		position = 15,
		section = cardinalKeybindingSnap,
		description = "Rotate camera a user defined number of degrees counterclockwise<br/>" +
				"Based on Rotation Degree"
	)
	default Keybind rotateCounterclockwiseKey() { return new Keybind(KeyEvent.VK_UNDEFINED, 0);}

	@ConfigItem(
		keyName = "rotateAfterSnap",
		name = "Rotate After Snap",
		position = 16,
		description = "Snap to the closest cardinal direction before rotation<br/>" +
				"Applies to all rotation keybindings"
	)
	default boolean rotateAfterSnap()
	{
		return false;
	}

	@ConfigItem(
		keyName = "rotateDegree",
		name = "Rotation Degree",
		position = 17,
		description = "Rotation value for clockwise and counterclockwise rotation keybindings"
	)
	default int rotateDegree()
	{
		return 90;
	}

	@ConfigItem(
		keyName = "deprioritizeInChat",
		name = "Disable Keybindings in Chat",
		position = 18,
		description = "Disable plugin keybindings while typing in chat<br/>" +
				"If the \"Key Remapping\" plugin is off, chat is auto focused and keybindings will not trigger"
	)
	default boolean deprioritizeInChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "deprioritizeInInterfaces",
		name = "Disable Keybindings in Interfaces",
		position = 19,
		description = "Disable plugin keybindings while interfaces are capturing input"
	)
	default boolean deprioritizeInInterfaces()
	{
		return false;
	}
}

package com.compassCameraControl;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.event.KeyEvent;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.HashTable;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.SoundEffectID;
import net.runelite.api.WidgetNode;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.vars.InputType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Compass Camera Control",
	description = "Expands compass functionality",
	tags = {"camera, compass, control, navigation, usability, convenience"}
)
public class CompassCameraControlPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private CompassCameraControlConfig config;

	@Inject
	private KeyManager keyManager;


	private static final int NORTH_YAW = 0;
	private static final int WEST_YAW = 4096;
	private static final int SOUTH_YAW = 8192;
	private static final int EAST_YAW = 12288;

	private static final Map<Character, Integer> directionMap = Map.of(
		'N', NORTH_YAW,
		'S', SOUTH_YAW,
		'E', EAST_YAW,
		'W', WEST_YAW
	);

	private static final String SNAP_FACING = "Snap Facing";
	private static final String SNAP_CARDINAL = "Snap Cardinal";
	private static final String CYCLE_CARDINAL = "Cycle Cardinal";
	private static final String SNAP_THEN_CYCLE = "Snap Then Cycle";
	private static final long HYBRID_CYCLE_TIMEOUT_MS = 2000L;

	private long lastHybridClickTimeMs;
	private volatile boolean topLevelInterfaceOpen;

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		topLevelInterfaceOpen = config.deprioritizeInInterfaces() && isTopLevelInterfaceOpen(-1, false);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		topLevelInterfaceOpen = config.deprioritizeInInterfaces() && isTopLevelInterfaceOpen(event.getGroupId(), event.isUnload());
	}


	private boolean isTopLevelInterfaceOpen(int closingGroupId, boolean closingUnload)
	{
		try
		{
			HashTable<WidgetNode> table = client.getComponentTable();
			if (table == null)
			{
				return false;
			}

			WidgetNode osrsStretchMain = table.get(InterfaceID.ToplevelOsrsStretch.MAINMODAL);
			WidgetNode osrsStretchFloat = table.get(InterfaceID.ToplevelOsrsStretch.FLOATER);
			WidgetNode preEocMain = table.get(InterfaceID.ToplevelPreEoc.MAINMODAL);
			WidgetNode preEocFloat = table.get(InterfaceID.ToplevelPreEoc.FLOATER);
			WidgetNode toplevelMain = table.get(InterfaceID.Toplevel.MAINMODAL);
			WidgetNode toplevelFloat = table.get(InterfaceID.Toplevel.FLOATER);

			int openCount = 0;
			WidgetNode onlyOpen = null;
			if (osrsStretchMain != null) { openCount++; onlyOpen = osrsStretchMain; }
			if (osrsStretchFloat != null) { openCount++; onlyOpen = osrsStretchFloat; }
			if (preEocMain != null) { openCount++; onlyOpen = preEocMain; }
			if (preEocFloat != null) { openCount++; onlyOpen = preEocFloat; }
			if (toplevelMain != null) { openCount++; onlyOpen = toplevelMain; }
			if (toplevelFloat != null) { openCount++; onlyOpen = toplevelFloat; }

			if (openCount == 0)
			{
				return false;
			}

			if (openCount == 1 && closingUnload && onlyOpen.getId() == closingGroupId)
			{
				return false;
			}

			return true;
		}
		catch (Exception e)
		{
			log.warn("Interface suppression check failed", e);
			return false;
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (event.getOption().equals("Look North"))
		{
			if (config.shiftClickMode() != ShiftMode.OFF) {
				boolean shiftHeld = client.isKeyPressed(KeyCode.KC_SHIFT);
				if (config.shiftClickMode() == ShiftMode.ONSHIFT && !shiftHeld) return;
				if (config.shiftClickMode() == ShiftMode.OFFSHIFT && shiftHeld) return;
			}

			String newOption;
			switch (config.controlMode())
			{
				case SNAP_TO_FACING:
					newOption = SNAP_FACING;
					break;

				case SNAP_TO_CLOSEST:
					newOption = SNAP_CARDINAL;
					break;

				case SNAP_THEN_CYCLE:
					newOption = SNAP_THEN_CYCLE;
					break;

				case CYCLE:
				default:
					newOption = CYCLE_CARDINAL;
					break;
			}

			client.getMenu()
				.createMenuEntry(-1)
				.setType(MenuAction.RUNELITE_HIGH_PRIORITY)
				.setOption(newOption)
				.onClick(this::onCompassAction);
		}
	}

	public void onCompassAction(MenuEntry event)
	{
		switch (event.getOption())
		{
			case SNAP_FACING:
				facingYaw();
				client.playSoundEffect(SoundEffectID.UI_BOOP);
				break;

			case SNAP_CARDINAL:
				alignYaw();
				client.playSoundEffect(SoundEffectID.UI_BOOP);
				break;

			case SNAP_THEN_CYCLE:
				hybridSnapThenCycle();
				client.playSoundEffect(SoundEffectID.UI_BOOP);
				break;

			case CYCLE_CARDINAL:
				cycleYaw();
				client.playSoundEffect(SoundEffectID.UI_BOOP);
				break;
		}
	}

	@Provides
	@Singleton
	CompassCameraControlConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CompassCameraControlConfig.class);
	}

	private int[] cycleOrderToYaws()
	{
		// Retain only "N", "E", "S", "W"
		String cycleOrder = config.cycleOrder().toUpperCase().replaceAll("[^NESW]", "")
			.chars()
			.distinct()
			.limit(4)
			.collect(StringBuilder::new,
				StringBuilder::appendCodePoint,
				StringBuilder::append)
			.toString();

		if (cycleOrder.isEmpty())
		{
			return new int[]{ NORTH_YAW, SOUTH_YAW, EAST_YAW, WEST_YAW };
		}

		return cycleOrder.chars()
			.map(c -> directionMap.get((char) c))
			.toArray();
	}

	private void cycleYaw()
	{
		// Overloaded method so cycleOrderToYaws isn't called twice when using hybridSnapThenCycle()
		cycleYaw(cycleOrderToYaws());
	}

	private void cycleYaw(int[] yawOrder)
	{
		int currentYaw = client.getCameraYaw();
		int nextYaw = yawOrder[0];

		for (int i = 0; i < yawOrder.length; i++)
		{
			if (yawOrder[i] == currentYaw)
			{
				nextYaw = yawOrder[(i + 1) % yawOrder.length];
				break;
			}
		}

		client.setCameraYawTarget(nextYaw);
	}

	private void alignYaw()
	{
		// Overloaded method so vanilla alignYaw users maintain the same functionality
		alignYaw(new int[]{ NORTH_YAW, SOUTH_YAW, EAST_YAW, WEST_YAW });
	}

	private void alignYaw(int[] yaws)
	{
		int currentYaw = client.getCameraYawTarget();
		int closestYaw = yaws[0];
		int diff = Math.abs(currentYaw - yaws[0]);
		int closestDistance = Math.min(diff, 16384 - diff);

		for (int i = 1; i < yaws.length; i++) {
			diff = Math.abs(currentYaw - yaws[i]);
			int distance = Math.min(diff, 16384 - diff);
			if (distance < closestDistance) {
				closestYaw = yaws[i];
				closestDistance = distance;
			}
		}

		client.setCameraYawTarget(closestYaw);
	}

	private void hybridSnapThenCycle()
	{
		long nowMs = System.currentTimeMillis();
		int currentYaw = client.getCameraYaw();
		int[] allowedYaws = cycleOrderToYaws();

		// Check if currentYaw is in the allowed cardinal set
		boolean isOnAllowedCardinal = false;
		for (int yaw : allowedYaws)
		{
			if (yaw == currentYaw)
			{
				isOnAllowedCardinal = true;
				break;
			}
		}

		if (isOnAllowedCardinal && (nowMs - lastHybridClickTimeMs) <= HYBRID_CYCLE_TIMEOUT_MS)
		{
			cycleYaw(allowedYaws);
		}
		else
		{
			alignYaw(allowedYaws);
		}

		lastHybridClickTimeMs = nowMs;
	}

	private void facingYaw()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		// Multiply by 8 to get the yaw since below method returns range of 0 to 2047 and yaw was increased to 0 to 16383
		int playerOrientation = client.getLocalPlayer().getOrientation() * 8;
		int targetYaw;

		if (playerOrientation <= 8192) {
			targetYaw = 4096 * 2 - playerOrientation;
		} else {
			targetYaw = 12288 * 2 - playerOrientation;
		}

		client.setCameraYawTarget(targetYaw);
	}

	private static int degreesToYaw(int degrees) {
		return (int) Math.round(degrees * 16384.0 / 360.0);
	}

	private void rotateYaw(String s)
	{
		int currentYaw = client.getCameraYaw();
		int shift = s.equals("Flip") ? degreesToYaw(180) : degreesToYaw(config.rotateDegree());
		int targetYaw;

		if (config.rotateAfterSnap()) {
			alignYaw();
			// Above updates the yaw target in this tick, so use the target rather than the current yaw
			currentYaw = client.getCameraYawTarget();
		}

		if(s.equals("Clockwise")){
			targetYaw = currentYaw + shift;
		}
		else {
			targetYaw = currentYaw - shift;
		}

		// Wraps yaw into camera range [0,16384)
		targetYaw &= 16383;

		client.setCameraYawTarget(targetYaw);
	}

	private boolean shouldSuppressHotkeysForChat()
	{
		if (client.getVarcIntValue(VarClientID.MESLAYERMODE) != InputType.NONE.getType())
		{
			return true;
		}

		String chatInput = client.getVarcStrValue(VarClientID.CHATINPUT);
		if (chatInput != null && !chatInput.isEmpty())
		{
			return true;
		}

		return isChatboxCaretActive();
	}

	private boolean shouldSuppressHotkeysForInterfaces()
	{
		if (client.getFocusedInputFieldWidget() != null)
		{
			return true;
		}

		if (topLevelInterfaceOpen)
		{
			return true;
		}

		if (isWidgetHidden(InterfaceID.Chatbox.MES_LAYER_HIDE) || isWidgetHidden(InterfaceID.Chatbox.CHATDISPLAY))
		{
			return true;
		}

		return !isWidgetHidden(InterfaceID.Chatmenu.OPTIONS);
	}

	private boolean isWidgetHidden(int component)
	{
		Widget widget = client.getWidget(component);
		return widget == null || widget.isSelfHidden();
	}

	private boolean isChatboxCaretActive()
	{
		Widget chatboxInput = client.getWidget(InterfaceID.Chatbox.INPUT);
		if (chatboxInput != null && !chatboxInput.isSelfHidden())
		{
			String text = chatboxInput.getText();
			return text != null && text.contains("*");
		}

		return false;
	}


	private final KeyListener keyListener = new KeyListener() {
		@Override
		public void keyTyped(KeyEvent event) { }

		@Override
		public void keyReleased(KeyEvent event) { }

		@Override
		public void keyPressed(KeyEvent event) {
			if ((config.deprioritizeInChat() && shouldSuppressHotkeysForChat()) || (config.deprioritizeInInterfaces() && shouldSuppressHotkeysForInterfaces()))
			{
				return;
			}

			boolean handledEvent = true;
			if (config.snapFacingKey().matches(event)) {
				facingYaw();
			} else if (config.snapCloseKey().matches(event)) {
				alignYaw();
			} else if (config.cycleCardinalKey().matches(event)) {
				cycleYaw();
			} else if (config.snapThenCycleKey().matches(event)) {
				hybridSnapThenCycle();
			} else if (config.lookNorthKey().matches(event)) {
				client.setCameraYawTarget(NORTH_YAW);
			} else if (config.lookSouthKey().matches(event)) {
				client.setCameraYawTarget(SOUTH_YAW);
			} else if (config.lookEastKey().matches(event)) {
				client.setCameraYawTarget(EAST_YAW);
			} else if (config.lookWestKey().matches(event)) {
				client.setCameraYawTarget(WEST_YAW);
			} else if (config.rotateFlipKey().matches(event)) {
				rotateYaw("Flip");
			} else if (config.rotateClockwiseKey().matches(event)) {
				rotateYaw("Clockwise");
			} else if (config.rotateCounterclockwiseKey().matches(event)) {
				rotateYaw("Counterclockwise");
			} else {
				handledEvent = false;
			}

			if (handledEvent) {
				event.consume();
			}
		}
	};

	@Override
	protected void startUp() throws Exception {
		keyManager.registerKeyListener(keyListener);
	}

	@Override
	protected void shutDown() throws Exception {
		topLevelInterfaceOpen = false;
		keyManager.unregisterKeyListener(keyListener);
	}
}

package com.compassCameraControl;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum ControlMode
{

	CYCLE("Cycle"),
	SNAP_TO_CLOSEST("Snap to Closest"),
	SNAP_TO_FACING("Snap to Facing"),
	SNAP_THEN_CYCLE("Snap then Cycle"),
	;

	private final String name;

	@Override
	public String toString()
	{
		// for config option dropdown to show proper capitalization
		return name;
	}
}

package com.compassCameraControl;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum ShiftMode
{

	OFF("Off"),
	ONSHIFT("On Shift"),
	OFFSHIFT("Off Shift"),
	;

	private final String name;

	@Override
	public String toString()
	{
		// for config option dropdown to show proper capitalization
		return name;
	}
}

